def sl(xr,yr,zmin=0.9):
    m=(P[:,0]>xr[0])&(P[:,0]<xr[1])&(P[:,1]>yr[0])&(P[:,1]<yr[1])&(P[:,2]>zmin); return P[m]
# left/middle divider: scan y bins around -0.21
